function download(content,name,type){const url=URL.createObjectURL(content instanceof Blob?content:new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)}
async function exportRecords(mode){
 if(accountLoading)throw Error('계정과 기록을 확인 중이에요. 확인이 끝난 뒤 내보내주세요.');
 if(recovery){download(recovery,'haze-flow-recovery.json','application/json');return}
 const owner=key,exportDate=date,store=photoStore,data=await readBackupState({storage:recordStorage,key:owner,getKey:()=>key});
 const safeDownload=(...args)=>{if(owner!==key)throw Error('계정이 바뀌어 내보내기를 중단했어요.');download(...args)};
 if(mode==='backup'){const {photoBackup}=await import('./photo-export.js');safeDownload(JSON.stringify(await photoBackup(data,store),null,2),`haze-flow-backup-${todayKey()}.json`,'application/json');return}
 if(mode==='image'){await exportImage(data,exportDate,store,()=>owner===key);return}
 if(collectPhotoRefs(data,mode==='all'?null:[exportDate]).length){const {documentZip}=await import('./photo-export.js');const zip=await documentZip(data,[exportDate],store,mode==='all');safeDownload(zip,`haze-flow-${mode==='all'?'all-records':exportDate}.zip`,'application/zip');return}
 safeDownload(mode==='all'?allDocument(data):dayDocument(data,exportDate),`haze-flow-${mode==='all'?'all-records':exportDate}.md`,'text/markdown;charset=utf-8');
}
async function exportImage(data,date,photoStore,isCurrent){
 await document.fonts.ready;const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d'),blocks=[],width=1200,pad=76,refs=new Map(collectPhotoRefs(data,[date]).map(p=>[p.id,p]));
 for(const source of dayDocument(data,date).split('\n')){const photo=source.match(/^!\[.*\]\(photos\/([-a-zA-Z0-9_]+)\.jpg\)$/);if(photo){const ref=refs.get(photo[1]);if(ref){const ratio=Math.min((width-pad*2)/ref.width,480/ref.height);blocks.push({type:'photo',ref,w:ref.width*ratio,h:ref.height*ratio,height:ref.height*ratio+24});}continue}
 const heading=source.startsWith('#'),text=source.replace(/^#{1,3}\s/,'').replace(/^- \[x\] /,'✓ ').replace(/^- \[ \] /,'□ ');ctx.font=`${heading?'600':'400'} 24px sans-serif`;let row='';for(const c of text){if(ctx.measureText(row+c).width>width-pad*2){blocks.push({text:row,heading,height:42});row=c}else row+=c}blocks.push({text:row,heading,height:42});}
 const pages=[];let page=[],height=0;for(const block of blocks){if(height+block.height>6200&&page.length){pages.push(page);page=[];height=0}page.push(block);height+=block.height}if(page.length)pages.push(page);
 for(let i=0;i<pages.length;i++){canvas.width=width;canvas.height=180+Math.ceil(pages[i].reduce((n,b)=>n+b.height,0));ctx.fillStyle='#faf9fc';ctx.fillRect(0,0,width,canvas.height);ctx.fillStyle='#887599';ctx.font='20px sans-serif';ctx.fillText(`haze flow · ${date}${pages.length>1?` · ${i+1}/${pages.length}`:''}`,pad,65);let y=130;for(const b of pages[i]){if(b.type==='photo'){const blob=await photoStore.get(b.ref.id);if(!blob)throw Error('내보낼 사진을 찾을 수 없어요.');const bitmap=await createImageBitmap(blob);ctx.drawImage(bitmap,pad,y,b.w,b.h);bitmap.close()}else{ctx.fillStyle=b.heading?'#6c587e':'#39313f';ctx.font=`${b.heading?'600':'400'} 24px sans-serif`;ctx.fillText(b.text,pad,y)}y+=b.height}const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('이미지를 만들지 못했어요.');if(!isCurrent())throw Error('계정이 바뀌어 내보내기를 중단했어요.');download(blob,`haze-flow-${date}${pages.length>1?'-'+(i+1):''}.png`,'image/png');}
}
